engine.buildAskEliPrompt:
function buildAskEliPrompt(input) {
  var CAP = 20;
  var question = String(input.question || "").trim();
  var docText = String(input.docText || "");
  var selectionText = String(input.selectionText || "").trim();
  var attachmentPrefix = String(input.attachmentPrefix || "");
  var history = Array.isArray(input.history) ? input.history : [];
  var modifyMode = !!input.modifyMode;
  var hasRedlines = !!input.hasRedlines;
  var roster = input.roster || null;
  var useAnchors = !!input.useAnchors;
  var currentUserName = String(input.currentUserName || "Andrew");

  // History block — last 10 turns max. Plain text, no JSON/HTML.
  var historyBlock = "";
  if (history.length) {
    historyBlock = history.slice(-CAP).map(function (turn) {
      var role = turn.role === "model" ? "ELI" : "User";
      return role + ": " + String(turn.content || "");
    }).join("\n");
  }

  // Selection-aware mode block. FROM v2 qaModeTargetSelection.
  var modeBlock = "";
  if (selectionText && selectionText.length > 4) {
    modeBlock =
      "\n    CONTEXTUAL ANALYSIS RULE:\n" +
      "    - The user has highlighted a specific section (TARGET SELECTION).\n" +
      "    - Focus your answer on that selection.\n" +
      "    - HOWEVER, you MUST cross-reference the FULL DOCUMENT CONTEXT to check for definitions, conflicting clauses, or overriding terms that affect the selection.\n";
  }

  // Always-broad mode — falls back to general legal knowledge when the
  // doc doesn't contain the answer. FROM v2 qaModeBroad.
  var broadBlock =
    "\n    MODE: BROAD / CONSULTANT\n" +
    "    - Base your facts on the document.\n" +
    "    - If the user asks for opinions, explanations, or 'market standards' that are not in the file, USE YOUR GENERAL KNOWLEDGE to answer helpfully.\n" +
    "    - FORMATTING: Use HTML tags for structure (<b>bold</b>, <ul><li>lists</li></ul>, <br> breaks).\n";

  // Author roster block — only when redlines present + roster provided.
  // FROM v2 qaAuthorRoster + qaRedlineNote.
  var rosterBlock = "";
  if (hasRedlines && roster && typeof roster === "object") {
    var internal = [], external = [], unknown = [];
    Object.keys(roster).forEach(function (name) {
      var side = String(roster[name] || "").toLowerCase();
      if (side === "internal") internal.push(name);
      else if (side === "external") external.push(name);
      else unknown.push(name);
    });
    var firstUnknown = unknown[0] || "";
    rosterBlock =
      "\n\n    CONFIRMED AUTHOR ROSTER (USER-VERIFIED GROUND TRUTH — TRUST THIS OVER ANY HEURISTIC):\n" +
      "    - INTERNAL / Colgate side: " + (internal.join(", ") || "(none)") + "\n" +
      "    - EXTERNAL / Counterparty side: " + (external.join(", ") || "(none)") + "\n" +
      "    - UNKNOWN side: " + (unknown.join(", ") || "(none)") + "\n" +
      "    Use these classifications verbatim. For UNKNOWN authors, refer by name without claiming a side. " +
      (firstUnknown ? "(e.g. \"" + firstUnknown + " inserted...\")" : "") + "\n";
  }
  var redlineNote = hasRedlines
    ? ("\n    REDLINE NOTE: This document contains tracked changes. Edits are marked inline as " +
       "[INSERTED by Author: text], [DELETED by Author: text], [MOVED FROM by Author: text], or " +
       "[MOVED TO by Author: text]. The current Colgate user is \"" + currentUserName + "\". " +
       "Use \"you\"/\"your\" ONLY for edits whose author matches the current user. For other internal " +
       "edits, name the colleague (e.g. \"Your colleague X inserted...\"). For external edits, identify " +
       "the counterparty by name. Do NOT include bracket markers in your answer text — describe naturally." +
       rosterBlock + "\n")
    : "";

  // Modify-mode task instruction. FROM v2 qaTaskModification.
  var taskBlock;
  if (modifyMode) {
    taskBlock =
      "TASK: You may MODIFY the document. If the user is asking to change/rewrite/strengthen/draft a specific clause, return RAW JSON:\n" +
      "    {\n" +
      "      \"action\": \"replace_text\",\n" +
      "      \"target_original\": \"EXACT_VERBATIM_STRING_FROM_DOCUMENT_TO_REPLACE\",\n" +
      "      \"proposed_new\": \"YOUR_STRONGER_OR_NEW_TEXT\",\n" +
      "      \"explanation\": \"Short summary of what changed and why.\"\n" +
      "    }\n" +
      "    CRITICAL: target_original must NOT include leading section numbers/letters/bullets — Word's search API can't match auto-numbered list formatting. Start with the first alphabetical word.\n" +
      "    If the user is NOT asking to modify a specific string, fall back to the standard answer shape:\n" +
      "    { \"answer\": \"<HTML answer with [N] markers>\", \"citations\": [\"verbatim excerpt for [1]\", ...], \"followups\": [\"4-8 word user command 1\", \"4-8 word user command 2\"] }\n";
  } else {
    // Standard answer task. FROM v2 qaTaskStandard.
    taskBlock =
      "TASK: Return RAW JSON (no markdown, no preamble):\n" +
      "    { \"answer\": \"<HTML answer with [N] markers inline next to claims>\", \"citations\": [\"verbatim excerpt for [1]\", \"verbatim excerpt for [2]\"], \"followups\": [\"4-8 word user command 1\", \"4-8 word user command 2\"] }\n" +
      "    INLINE CITATION RULE:\n" +
      "    - Every entry in 'citations' MUST have a matching [N] marker placed INLINE in 'answer', adjacent to the claim it supports.\n" +
      "    - Number of [N] markers MUST equal length of citations array.\n" +
      "    - If you cannot find a verbatim excerpt to cite for a claim, do NOT include that claim's citation.\n" +
      "    'followups' must contain EXACTLY 2 concise actionable commands (4-8 words each) written from the user's perspective (e.g. \"Draft a mutual version\", \"Explain the key risks\"), NOT questions from you.\n";
  }

  // Selection block — verbatim text the user highlighted, capped at 4000
  // chars to keep prompt size sane.
  var selectionBlock = (selectionText && selectionText.length > 4)
    ? ("\n    TARGET SELECTION (USER HIGHLIGHTED):\n    \"\"\"\n    " + selectionText.substring(0, 4000) + "\n    \"\"\"\n")
    : "";

  // Document text — trimmed to 200K chars. When useAnchors is true, the
  // docText already has _ELI_QA_<id> anchors embedded by getQaAnchorPayload.
  var docHeader = useAnchors
    ? "    LIVE WORD DOCUMENT (FULL CONTEXT, paragraph-indexed JSON):\n"
    : "    LIVE WORD DOCUMENT (FULL CONTEXT):\n";
  var docBlock = docText
    ? (docHeader + "    " + docText.substring(0, 500000) + "\n")
    : "    (No document text available.)\n";

  // Final assembly. attachmentPrefix is prepended (e.g. for "both" scope
  // or attached-only). It's already shaped with `=== ATTACHED FILE ===`
  // headers by buildAttachmentPrefix.
  return [
    "You are 'ELI', an AI legal assistant for Colgate-Palmolive's legal team.",
    "    PERSPECTIVE: The user asking is ALWAYS a Colgate lawyer reviewing this agreement from Colgate's side.",
    "    When the user says 'we', 'us', or 'our', they mean Colgate. Treat the other party as the counterparty.",
    historyBlock ? "    CONVERSATION SO FAR:\n" + historyBlock : "",
    "    CURRENT QUESTION: " + question,
    selectionBlock,
    attachmentPrefix ? "    " + attachmentPrefix : "",
    docBlock,
    modeBlock + broadBlock + redlineNote,
    taskBlock,
  ].filter(Boolean).join("\n");
}

// FROM v2 _isTranslateRequest. Cheap regex; init checks before sending
// to AI and routes through a separate prompt path.

engine.isTranslateRequest:
function isTranslateRequest(question) {
  if (!question) return false;
  var s = String(question);
  return /\btranslate(d|s|ing)?\b/i.test(s) || /\btranslation\b/i.test(s);
}

// Translate prompt builder. Two variants: HTML (when selection contains
// tables) preserves table markup; text strips to plain. FROM v2 lines
// 11260-11328.

engine.buildTranslatePrompt:
function buildTranslatePrompt(input) {
  var question = String(input.question || "").trim();
  var sourceText = String(input.sourceText || "").trim();
  var sourceHtml = String(input.sourceHtml || "").trim();
  var hasTables = /<table[\s>]/i.test(sourceHtml);
  if (hasTables) {
    return [
      "You are a legal translator.",
      "TASK: " + question,
      "Preserve all HTML table markup (<table>, <tr>, <td>, <th>) — translate ONLY the text content inside.",
      "Return RAW JSON: { \"hasTables\": true, \"html\": \"<the translated HTML>\" }",
      "",
      "SOURCE HTML:",
      sourceHtml.substring(0, 100000),
    ].join("\n");
  }
  return [
    "You are a legal translator.",
    "TASK: " + question,
    "Return RAW JSON: { \"hasTables\": false, \"text\": \"<the translated plain text>\" }",
    "",
    "SOURCE TEXT:",
    sourceText.substring(0, 100000),
  ].join("\n");
}

// Build the attachment prefix for the standard prompt. FROM v2
// _buildAttachmentPrefix (line 11352). Concatenates active template payload,
// attached-text file payload, and PDF marker (the actual PDF bytes flow as
// inlineData in the AI call, not in the text prefix).

engine.buildAttachmentPrefix:
function buildAttachmentPrefix(input) {
  var pre = "";
  if (input.activeTemplatePayload) pre += String(input.activeTemplatePayload) + "\n";
  if (input.attachedText) {
    var name = input.attachedName || "document";
    var text = String(input.attachedText).substring(0, 500000);
    pre += '=== ATTACHED FILE (' + name + ') ===\n"""\n' + text + '\n"""\n';
  }
  if (input.attachedPdfMarker) {
    var pdfName = input.attachedName || "document";
    pre += '=== ATTACHED PDF (' + pdfName + ') ===\n(Content provided as inline PDF data below)\n';
  }
  return pre;
}

// ─── AI response parsing ─────────────────────────────────────────────

// Robust JSON-extract from Gemini response. FROM v2 tryParseGeminiJSON.
// AI sometimes wraps JSON in ```json fences or adds preamble; strip and
// try to parse. Return parsed object OR `{answer: "<raw text>"}` fallback.

engine.parseAiResponse:
function parseAiResponse(raw) {
  if (raw == null) return { answer: "" };
  var s = String(raw).trim();
  // Strip ```json … ``` fences.
  s = s.replace(/^```(?:json|html)?\s*/i, "").replace(/```\s*$/, "").trim();
  // Try direct parse.
  try {
    var direct = JSON.parse(s);
    if (direct && typeof direct === "object") return direct;
  } catch (e) { /* fall through */ }
  // Find first { and last } — Gemini often wraps JSON in chatter.
  var first = s.indexOf("{"), last = s.lastIndexOf("}");
  if (first !== -1 && last > first) {
    try {
      var sliced = JSON.parse(s.slice(first, last + 1));
      if (sliced && typeof sliced === "object") return sliced;
    } catch (e) { /* fall through */ }
  }
  // Plain HTML fallback.
  return { answer: s };
}

// ─── History capping ─────────────────────────────────────────────────

// Cap history to prevent prompt bloat. FROM v2 chatHistory.push override.

engine.capHistory:
function capHistory(history) {
  var CAP = 20;
  if (!Array.isArray(history)) return [];
  if (history.length <= CAP) return history.slice();
  return history.slice(history.length - CAP);
}

// ─── Citation rendering ──────────────────────────────────────────────

// Walks `[N]` markers in the answer HTML and replaces them with citation
// chip placeholders that init wires up to actual click handlers.
// Returns { html, count } so the view can decide whether to show a
// citations footer if any [N] is unmatched. FROM v2 addChatBubble citation
// loop (line 11809).

engine.renderCitations:
function renderCitations(answerHtml, citations) {
  var html = String(answerHtml || "");
  if (!Array.isArray(citations) || !citations.length) {
    return { html: html, count: 0 };
  }
  var matched = 0;
  // Replace each [N] with a chip span. Init wires data-cite-n on click
  // to call jumpToBookmark / highlightCitation against the doc.
  var chipped = html.replace(/(\s*)\[(\d+)\](\s*)([.,;:!?\)\]])?/g, function (full, lead, n, trail, punct) {
    var idx = parseInt(n, 10) - 1;
    if (idx < 0 || idx >= citations.length) return full;
    matched++;
    var c = citations[idx] || {};
    var cText = (typeof c === "string") ? c : (c.text || c.excerpt || "");
    var cId = (typeof c === "object" && c.id) ? c.id : "";
    // Pin chip; init wires data-cite-text + data-cite-id.
    var cleanText = String(cText).replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    return (lead || "") +
      '<span class="_eli3_chat_cite" data-cite-n="' + n + '" data-cite-id="' + cId + '" ' +
      'data-cite-text="' + cleanText + '" title="Click to locate in document">📍</span>' +
      (punct || "") + (trail || "");
  });
  return { html: chipped, count: matched, total: citations.length };
}

// ─── Markdown-lite ───────────────────────────────────────────────────

// FROM v2 addChatBubble plain-text branch — converts **bold**, *italic*,
// and \n to HTML when the caller passes raw text rather than HTML. Used
// for user bubbles + activity-feed restoration.

engine.markdownLite:
function markdownLite(text) {
  var s = String(text == null ? "" : text);
  // Escape first.
  s = s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  // Bold
  s = s.replace(/\*\*([^*]+)\*\*/g, "<b>$1</b>");
  // Italic (single asterisks not adjacent to bold)
  s = s.replace(/(^|[^*])\*([^*]+)\*([^*]|$)/g, "$1<i>$2</i>$3");
  // Newlines
  s = s.replace(/\n/g, "<br>");
  return s;
}

// ─── Engine entry ────────────────────────────────────────────────────

// Build the prompt, call AI, parse the response, return both the parsed
// shape (action/answer/citations/followups) and the new history. Per
// evalBundle isolation, sibling helpers come in via providers.

engine.analyze:
function analyze(input, providers) {
  var ai = providers && providers.ai;
  if (!ai || typeof ai.complete !== "function") {
    return Promise.reject(new Error("ask_eli: providers.ai.complete missing"));
  }
  var buildPrompt = providers && providers.buildPrompt;
  var capHist     = providers && providers.capHistory;
  var parseAi     = providers && providers.parseAiResponse;
  if (typeof buildPrompt !== "function" || typeof capHist !== "function" || typeof parseAi !== "function") {
    return Promise.reject(new Error("ask_eli: providers.buildPrompt + capHistory + parseAiResponse required"));
  }

  var prompt = buildPrompt(input);
  var aiOpts = {};
  if (input.signal) aiOpts.signal = input.signal;
  // PDF inline data (Gemini multimodal). Passed through unmodified.
  if (input.inlineData) {
    aiOpts.inlineData = input.inlineData;
  }
  aiOpts.sanitize = false;

  return Promise.resolve(ai.complete(prompt, aiOpts)).then(function (rawAnswer) {
    var parsed = parseAi(rawAnswer);
    // Normalize shape — guard against missing fields.
    var answer = parsed.answer || (parsed.action ? "" : String(rawAnswer));
    var newHistoryEntry = parsed.action === "replace_text"
      ? "Action Card: Document Modification Proposed."
      : answer;
    var newHistory = capHist((input.history || []).concat([
      { role: "user", content: input.question },
      { role: "model", content: newHistoryEntry },
    ]));
    return {
      raw: rawAnswer,
      action: parsed.action || null,
      target_original: parsed.target_original || "",
      proposed_new: parsed.proposed_new || "",
      explanation: parsed.explanation || "",
      answer: answer,
      citations: Array.isArray(parsed.citations) ? parsed.citations : [],
      followups: Array.isArray(parsed.followups) ? parsed.followups.slice(0, 2) : [],
      history: newHistory,
      overview: String(answer || "").replace(/<[^>]+>/g, "").substring(0, 200),
      provenance: {
        kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
        toolVersion: "v3.1",
        promptVersion: input.modifyMode ? "ask_eli_modify_v1" : "ask_eli_qa_v1",
        model: (ai.currentModel && ai.currentModel()) || null,
        docHash: input.docHash || null,
        timestamp: Date.now(),
      },
    };
  });
}

view.renderChat:
function renderChat(opts) {
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;
  var initialHistory = opts.history || [];
  var welcomeName = opts.welcomeName || "there";
  var docTypeLabel = opts.docTypeLabel || "document";
  var initialSelection = opts.selectionText || "";
  var initialAttachment = opts.attachment || null; // { name, kind: "pdf"|"file"|"template" }
  var initialScope = opts.scope || "attached"; // "attached" | "both"
  var onSend = opts.onSend || function () {};
  var onBack = opts.onBack || function () {};
  var onClearHistory = opts.onClearHistory || function () {};
  var onAttachOpen = opts.onAttachOpen || function () {};
  var onAttachClear = opts.onAttachClear || function () {};
  var onScopeChange = opts.onScopeChange || function () {};
  var onModifyModeChange = opts.onModifyModeChange || function () {};
  var onImprove = opts.onImprove || null; // optional rewrite-prompt helper
  var onCitationClick = opts.onCitationClick || function () {};
  var onApplyAction = opts.onApplyAction || function () {};
  var onRejectAction = opts.onRejectAction || function () {};
  var onFollowup = opts.onFollowup || null;

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Compose the root.
  mount.innerHTML = "";
  var root = document.createElement("div");
  root.className = "_eli3_ae_root _eli3_chat_root";
  root.innerHTML =
    '<div class="_eli3_ae_bar">' +
      '<button class="_eli3_ae_back" title="Back">←</button>' +
      '<div class="_eli3_ae_title">🤖 Ask ELI</div>' +
      '<button class="_eli3_chat_clear" title="Clear conversation">🧹</button>' +
    '</div>' +
    '<div class="_eli3_chat_scroll" id="_eli3_chat_scroll"></div>' +
    '<div class="_eli3_chat_selpreview" id="_eli3_chat_selpreview" hidden></div>' +
    '<div class="_eli3_chat_scopebar" id="_eli3_chat_scopebar" hidden>' +
      '<button type="button" class="_eli3_chat_scopeseg" data-scope="attached">Attached</button>' +
      '<button type="button" class="_eli3_chat_scopeseg" data-scope="both">Both</button>' +
    '</div>' +
    '<div class="_eli3_chat_inputrow">' +
      '<textarea class="_eli3_chat_input" id="_eli3_chat_input" rows="2" placeholder="Ask ELI about this document…"></textarea>' +
      '<div class="_eli3_chat_toolbar">' +
        '<button type="button" class="_eli3_chat_tool _eli3_chat_improve" id="_eli3_chat_improve" title="Improve prompt">✨</button>' +
        '<button type="button" class="_eli3_chat_tool _eli3_chat_attach" id="_eli3_chat_attach" title="Attach file or template">📎</button>' +
        '<label class="_eli3_chat_tool _eli3_chat_drafttoggle" id="_eli3_chat_drafttoggle" title="Draft a new clause">' +
          '<input type="checkbox" id="_eli3_chat_draftchk">' +
          '<span>Draft</span>' +
        '</label>' +
        '<div class="_eli3_chat_contexthint" id="_eli3_chat_contexthint">Whole document</div>' +
        '<button type="button" class="_eli3_chat_send" id="_eli3_chat_send" title="Send (Enter)">➤</button>' +
      '</div>' +
    '</div>';

  root.querySelector("._eli3_ae_back").onclick = onBack;
  root.querySelector("._eli3_chat_clear").onclick = onClearHistory;

  var scrollEl   = root.querySelector("#_eli3_chat_scroll");
  var selPrevEl  = root.querySelector("#_eli3_chat_selpreview");
  var scopeBarEl = root.querySelector("#_eli3_chat_scopebar");
  var inputEl    = root.querySelector("#_eli3_chat_input");
  var sendBtn    = root.querySelector("#_eli3_chat_send");
  var attachBtn  = root.querySelector("#_eli3_chat_attach");
  var improveBtn = root.querySelector("#_eli3_chat_improve");
  var draftChk   = root.querySelector("#_eli3_chat_draftchk");
  var ctxHintEl  = root.querySelector("#_eli3_chat_contexthint");

  var defaultPlaceholder = "Ask ELI about this " + docTypeLabel + "…";
  inputEl.placeholder = defaultPlaceholder;

  // ─── State (closure — no window globals) ─────────────────────────
  var state = {
    rewrite: false,                 // selection-chip rewrite toggle
    draft: !!draftChk.checked,      // toolbar draft-clause toggle
    scope: initialScope,
    attachment: initialAttachment,
    selectionText: initialSelection,
    selectionDismissed: false,
    selectionLast: "",
    inFlight: false,
  };

  function _modifyMode() { return state.rewrite || state.draft; }
  function _refreshPlaceholder() {
    if (state.rewrite) inputEl.placeholder = "How do you want to rewrite this clause?";
    else if (state.draft) inputEl.placeholder = "What clause would you like to draft?";
    else inputEl.placeholder = state.selectionText && state.selectionText.length > 4
      ? "Ask ELI about this section…"
      : defaultPlaceholder;
  }
  function _refreshContextHint() {
    if (state.selectionText && state.selectionText.trim().length > 4) {
      var words = state.selectionText.trim().split(/\s+/).length;
      ctxHintEl.textContent = "Selection · " + words + " word" + (words === 1 ? "" : "s");
      ctxHintEl.classList.add("_eli3_chat_contexthint_active");
    } else {
      ctxHintEl.textContent = "Whole document";
      ctxHintEl.classList.remove("_eli3_chat_contexthint_active");
    }
  }

  // ─── Bubble factory ──────────────────────────────────────────────
  function _scrollToBottom() {
    requestAnimationFrame(function () { scrollEl.scrollTop = scrollEl.scrollHeight; });
  }
  function _renderBubble(type, html) {
    var wrap = document.createElement("div");
    wrap.className = "_eli3_chat_bubble _eli3_chat_bubble_" + type;
    wrap.innerHTML = html;
    scrollEl.appendChild(wrap);
    _scrollToBottom();
    return wrap;
  }
  function addUserBubble(text) { _renderBubble("user", _esc(text).replace(/\n/g, "<br>")); }
  function addAiBubble(html, citations, followups, hybridNote) {
    var pieces = [];
    if (hybridNote) pieces.push('<div class="_eli3_chat_hybrid">' + hybridNote + '</div>');
    pieces.push(html);
    if (Array.isArray(followups) && followups.length) {
      pieces.push('<div class="_eli3_chat_followups">' +
        followups.slice(0, 2).map(function (f, i) {
          return '<button type="button" class="_eli3_chat_followup" data-followup-i="' + i + '">' +
            '✨ ' + _esc(f) + '</button>';
        }).join("") +
      '</div>');
    }
    var wrap = _renderBubble("ai", pieces.join(""));
    // Wire citation chips (rendered by engine.renderCitations into the html).
    Array.prototype.forEach.call(wrap.querySelectorAll("._eli3_chat_cite"), function (chip) {
      chip.onclick = function () {
        onCitationClick({
          n: chip.getAttribute("data-cite-n"),
          id: chip.getAttribute("data-cite-id"),
          text: chip.getAttribute("data-cite-text"),
        }, chip);
      };
    });
    // Wire follow-up clicks.
    Array.prototype.forEach.call(wrap.querySelectorAll("._eli3_chat_followup"), function (btn, i) {
      btn.onclick = function () {
        var fi = parseInt(btn.getAttribute("data-followup-i"), 10) || 0;
        if (typeof onFollowup === "function") onFollowup(followups[fi]);
        else { inputEl.value = followups[fi] || ""; inputEl.focus(); _doSend(); }
      };
    });
    return wrap;
  }
  function addSystemBubble(html) { _renderBubble("system", html); }
  function showLoader() {
    return _renderBubble("loader",
      '<span class="_eli3_chat_dot"></span>' +
      '<span class="_eli3_chat_dot"></span>' +
      '<span class="_eli3_chat_dot"></span>'
    );
  }
  function removeLoader(node) { if (node && node.parentNode) node.parentNode.removeChild(node); }

  // Action card — replace_text proposal. Reject + Apply (clean) + Apply
  // (with redlines) buttons, plus a redline-preview diff. FROM v2
  // renderActionCard (line 11555).
  function addActionCard(payload) {
    var explanation = payload.explanation || "";
    var orig = payload.target_original || "";
    var prop = payload.proposed_new || "";
    var diff = _renderDiff(orig, prop);
    var wrap = document.createElement("div");
    wrap.className = "_eli3_chat_bubble _eli3_chat_bubble_ai _eli3_chat_actioncard";
    wrap.innerHTML =
      '<div class="_eli3_chat_actioncard_head">📝 Document modification proposed</div>' +
      (explanation ? '<div class="_eli3_chat_actioncard_explanation">' + _esc(explanation) + '</div>' : "") +
      '<div class="_eli3_chat_actioncard_diff">' + diff + '</div>' +
      '<label class="_eli3_chat_actioncard_redline">' +
        '<input type="checkbox" id="_eli3_chat_ac_noredlines"> ' +
        '<span>Apply WITHOUT track-changes (clean replace)</span>' +
      '</label>' +
      '<div class="_eli3_chat_actioncard_actions">' +
        '<button type="button" class="_eli3_chat_actioncard_reject" id="_eli3_chat_ac_reject">Reject</button>' +
        '<button type="button" class="_eli3_chat_actioncard_apply" id="_eli3_chat_ac_apply">Apply</button>' +
      '</div>' +
      '<div class="_eli3_chat_actioncard_status" hidden></div>';
    scrollEl.appendChild(wrap);
    _scrollToBottom();
    var rejectBtn = wrap.querySelector("#_eli3_chat_ac_reject");
    var applyBtn  = wrap.querySelector("#_eli3_chat_ac_apply");
    var noRedChk  = wrap.querySelector("#_eli3_chat_ac_noredlines");
    var statusEl  = wrap.querySelector("._eli3_chat_actioncard_status");
    rejectBtn.onclick = function () {
      onRejectAction(payload);
      wrap.classList.add("_eli3_chat_actioncard_done");
      statusEl.hidden = false;
      statusEl.textContent = "✕ Rejected.";
      applyBtn.disabled = true; rejectBtn.disabled = true;
    };
    applyBtn.onclick = function () {
      applyBtn.disabled = true;
      rejectBtn.disabled = true;
      var orig = applyBtn.textContent;
      applyBtn.textContent = "Applying…";
      Promise.resolve(onApplyAction({
        target_original: payload.target_original,
        proposed_new: payload.proposed_new,
        anchorBookmark: payload.anchorBookmark,
        useRedlines: !noRedChk.checked,
      })).then(function (result) {
        applyBtn.textContent = "Applied ✓";
        wrap.classList.add("_eli3_chat_actioncard_done");
        statusEl.hidden = false;
        statusEl.textContent = result && result.message
          ? result.message
          : (noRedChk.checked ? "✓ Applied (clean)" : "✓ Applied with track changes");
      }).catch(function (err) {
        applyBtn.disabled = false;
        rejectBtn.disabled = false;
        applyBtn.textContent = orig;
        statusEl.hidden = false;
        statusEl.textContent = "⚠ " + (err && err.message || "Apply failed");
        statusEl.className = "_eli3_chat_actioncard_status _eli3_chat_actioncard_status_err";
      });
    };
    return wrap;
  }

  // Word-level diff renderer for action card preview. Cheap LCS-on-words
  // is good enough — production redline rebuild happens via runRaw.
  function _renderDiff(oldText, newText) {
    var oldWords = String(oldText || "").split(/(\s+)/);
    var newWords = String(newText || "").split(/(\s+)/);
    // LCS table.
    var m = oldWords.length, n = newWords.length;
    if (!m && !n) return '<i class="_eli3_chat_diff_empty">(no preview)</i>';
    var dp = new Array(m + 1);
    for (var i = 0; i <= m; i++) { dp[i] = new Array(n + 1); dp[i][0] = 0; }
    for (var j = 0; j <= n; j++) dp[0][j] = 0;
    for (var i2 = 1; i2 <= m; i2++) {
      for (var j2 = 1; j2 <= n; j2++) {
        if (oldWords[i2 - 1] === newWords[j2 - 1]) dp[i2][j2] = dp[i2 - 1][j2 - 1] + 1;
        else dp[i2][j2] = dp[i2 - 1][j2] >= dp[i2][j2 - 1] ? dp[i2 - 1][j2] : dp[i2][j2 - 1];
      }
    }
    var ops = [], ii = m, jj = n;
    while (ii > 0 || jj > 0) {
      if (ii > 0 && jj > 0 && oldWords[ii - 1] === newWords[jj - 1]) {
        ops.unshift({ t: "=", w: oldWords[ii - 1] }); ii--; jj--;
      } else if (jj > 0 && (ii === 0 || dp[ii][jj - 1] >= dp[ii - 1][jj])) {
        ops.unshift({ t: "+", w: newWords[jj - 1] }); jj--;
      } else { ops.unshift({ t: "-", w: oldWords[ii - 1] }); ii--; }
    }
    return ops.map(function (o) {
      if (o.t === "=") return _esc(o.w);
      if (o.t === "+") return '<span class="_eli3_chat_diff_add">' + _esc(o.w) + '</span>';
      return '<span class="_eli3_chat_diff_del">' + _esc(o.w) + '</span>';
    }).join("");
  }

  // Translate-result bubble. FROM v2 _runTranslateQuery render.
  function addTranslateBubble(opts) {
    var label = opts.hasTables
      ? '🌐 Translation · Table formatting preserved'
      : '🌐 Translation';
    var body = opts.hasTables
      ? '<div class="_eli3_chat_translate_table">' + (opts.html || "") + '</div>'
      : (opts.html || "");
    return addAiBubble(
      '<div class="_eli3_chat_translate_label">' + label + '</div>' + body
    );
  }

  // ─── Welcome / history replay ────────────────────────────────────
  if (!initialHistory.length) {
    addAiBubble(
      "🤖 <strong>ELI</strong>: Hi " + _esc(welcomeName) + "! What would you like to know about this " + _esc(docTypeLabel) + "?<br>" +
      '<em class="_eli3_chat_welcome_hint">' +
        "I can answer questions, explain clauses, summarize, draft new clauses, translate, and more. " +
        "Highlight text to focus on a section." +
      "</em>"
    );
  } else {
    initialHistory.forEach(function (turn) {
      if (!turn) return;
      if (turn.role === "user") addUserBubble(String(turn.content || ""));
      else if (turn.role === "model") addAiBubble(String(turn.content || ""));
    });
  }

  // ─── Selection chip ──────────────────────────────────────────────
  function setSelection(text) {
    var trimmed = String(text || "").trim();
    state.selectionText = trimmed;
    // Re-show the chip on a *new* selection (different than last).
    if (trimmed !== state.selectionLast) {
      state.selectionDismissed = false;
      state.selectionLast = trimmed;
    }
    if (!trimmed || trimmed.length < 4 || state.selectionDismissed) {
      selPrevEl.hidden = true;
      selPrevEl.innerHTML = "";
      // If chip vanishes, ensure rewrite toggle goes off (it lived inside chip).
      if (state.rewrite) { state.rewrite = false; onModifyModeChange(_modifyMode()); }
      _refreshPlaceholder();
      _refreshContextHint();
      return;
    }
    selPrevEl.hidden = false;
    var preview = trimmed.length > 240
      ? (trimmed.substring(0, 240).replace(/\S+$/, "").trim() + "…")
      : trimmed;
    var words = trimmed.split(/\s+/).length;
    selPrevEl.innerHTML =
      '<div class="_eli3_chat_selpreview_top">' +
        '<span class="_eli3_chat_selpreview_label">📍 Focus on selection · ' + words + ' words</span>' +
        '<button type="button" class="_eli3_chat_selpreview_dismiss" title="Dismiss">×</button>' +
      '</div>' +
      '<div class="_eli3_chat_selpreview_text">' + _esc(preview) + '</div>' +
      '<label class="_eli3_chat_selpreview_rewrite">' +
        '<input type="checkbox" id="_eli3_chat_rewritechk"' + (state.rewrite ? " checked" : "") + '>' +
        '<span id="_eli3_chat_rewritelbl">Rewrite this clause</span>' +
      '</label>';
    selPrevEl.querySelector("._eli3_chat_selpreview_dismiss").onclick = function () {
      state.selectionDismissed = true;
      selPrevEl.hidden = true;
      _refreshPlaceholder(); _refreshContextHint();
    };
    var rewriteChk = selPrevEl.querySelector("#_eli3_chat_rewritechk");
    rewriteChk.onchange = function () {
      state.rewrite = rewriteChk.checked;
      _refreshPlaceholder();
      onModifyModeChange(_modifyMode());
    };
    _refreshPlaceholder();
    _refreshContextHint();
  }
  setSelection(initialSelection);

  // ─── Attach button + scope bar ───────────────────────────────────
  function setAttachment(att) {
    state.attachment = att || null;
    if (att) {
      attachBtn.classList.add("_eli3_chat_attach_on");
      var name = att.name || "attached";
      var truncName = name.length > 22 ? name.substring(0, 20) + "…" : name;
      attachBtn.innerHTML = '📎 ' + _esc(truncName) + ' <span class="_eli3_chat_attach_x">✕</span>';
      attachBtn.title = "Click to detach: " + name;
      scopeBarEl.hidden = false;
    } else {
      attachBtn.classList.remove("_eli3_chat_attach_on");
      attachBtn.innerHTML = '📎';
      attachBtn.title = "Attach file or template";
      scopeBarEl.hidden = true;
    }
  }
  function setScope(scope) {
    state.scope = scope === "both" ? "both" : "attached";
    Array.prototype.forEach.call(scopeBarEl.querySelectorAll("._eli3_chat_scopeseg"), function (seg) {
      var active = seg.getAttribute("data-scope") === state.scope;
      seg.classList.toggle("_eli3_chat_scopeseg_active", active);
    });
  }
  setAttachment(initialAttachment);
  setScope(initialScope);

  attachBtn.onclick = function () {
    if (state.attachment) onAttachClear();
    else onAttachOpen();
  };
  Array.prototype.forEach.call(scopeBarEl.querySelectorAll("._eli3_chat_scopeseg"), function (seg) {
    seg.onclick = function () {
      var s = seg.getAttribute("data-scope");
      setScope(s);
      onScopeChange(s);
    };
  });

  // ─── Draft toggle ────────────────────────────────────────────────
  draftChk.onchange = function () {
    state.draft = draftChk.checked;
    _refreshPlaceholder();
    onModifyModeChange(_modifyMode());
  };

  // ─── Improve button ──────────────────────────────────────────────
  improveBtn.onclick = function () {
    if (!onImprove) return;
    var current = String(inputEl.value || "").trim();
    if (!current) return;
    improveBtn.disabled = true;
    improveBtn.textContent = "⏳";
    Promise.resolve(onImprove(current)).then(function (improved) {
      improveBtn.textContent = "✨";
      improveBtn.disabled = false;
      if (improved) inputEl.value = improved;
    }).catch(function () {
      improveBtn.textContent = "✨";
      improveBtn.disabled = false;
    });
  };

  // ─── Send ────────────────────────────────────────────────────────
  function _doSend() {
    if (state.inFlight) return;
    var question = String(inputEl.value || "").trim();
    if (!question) return;
    state.inFlight = true;
    inputEl.value = "";
    inputEl.style.height = "";
    sendBtn.disabled = true;
    addUserBubble(question);
    var loader = showLoader();

    // Snapshot mode flags BEFORE we reset them — caller decides how to
    // route based on these.
    var sendCtx = {
      modifyMode: _modifyMode(),
      rewrite: state.rewrite,
      draft: state.draft,
      scope: state.scope,
      hasAttachment: !!state.attachment,
      selectionText: state.selectionText,
    };

    Promise.resolve(onSend(question, sendCtx)).then(function (result) {
      removeLoader(loader);
      // Reset modify toggles after each AI response (FROM v2 line 7601).
      _resetModifyToggles();
      if (!result) return;
      if (result.action === "replace_text") {
        addActionCard({
          target_original: result.target_original,
          proposed_new: result.proposed_new,
          explanation: result.explanation,
          anchorBookmark: result.anchorBookmark,
        });
      } else if (result.translate) {
        addTranslateBubble(result.translate);
      } else {
        addAiBubble(result.answer || "", result.citations, result.followups, result.hybridNote);
      }
    }).catch(function (err) {
      removeLoader(loader);
      _resetModifyToggles();
      var msg = (err && err.message) || "Unknown error";
      if (/abort|cancel/i.test(msg)) addSystemBubble("⏹️ Request cancelled.");
      else addSystemBubble('❌ Error: <code>' + _esc(msg) + '</code>');
    }).then(function () {
      state.inFlight = false;
      sendBtn.disabled = false;
      inputEl.focus();
    });
  }
  function _resetModifyToggles() {
    state.rewrite = false;
    state.draft = false;
    if (draftChk) draftChk.checked = false;
    var rewriteChk = root.querySelector("#_eli3_chat_rewritechk");
    if (rewriteChk) rewriteChk.checked = false;
    _refreshPlaceholder();
    onModifyModeChange(false);
  }
  sendBtn.onclick = _doSend;

  // Enter sends; Shift+Enter newline. Auto-grow up to ~4 lines.
  inputEl.addEventListener("keydown", function (e) {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); _doSend(); }
  });
  inputEl.addEventListener("input", function () {
    inputEl.style.height = "auto";
    inputEl.style.height = Math.min(inputEl.scrollHeight, 120) + "px";
  });

  mount.appendChild(root);

  // Public surface init can call.
  return {
    setSelection: setSelection,
    setAttachment: setAttachment,
    setScope: setScope,
    setDocType: function (label) {
      docTypeLabel = label || "document";
      defaultPlaceholder = "Ask ELI about this " + docTypeLabel + "…";
      _refreshPlaceholder();
    },
    addUserBubble: addUserBubble,
    addAiBubble: addAiBubble,
    addSystemBubble: addSystemBubble,
    addActionCard: addActionCard,
    addTranslateBubble: addTranslateBubble,
    clearScroll: function () { scrollEl.innerHTML = ""; },
    focusInput: function () { inputEl.focus(); },
  };
}

// ─── Attach modal ────────────────────────────────────────────────────
// FROM v2 buildSourceMenuDialog. Two-tab modal: Upload File / Saved
// Templates. Uses showEliDialog as the host. opts.templates is an array
// of {id, label, content, library, category} from the templates store.

view.renderAttachDialog:
function renderAttachDialog(opts) {
  if (typeof showEliDialog !== "function") {
    if (typeof showToast === "function") showToast("Dialog primitive missing", "err");
    return;
  }
  var templates = opts.templates || [];
  var onPickFile = opts.onPickFile || function () {};
  var onPickTemplate = opts.onPickTemplate || function () {};

  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Group templates by library / agreementType.
  var grouped = {};
  templates.forEach(function (t) {
    if (!t || !t.id || String(t.id).charAt(0) === "_") return;
    var lib = t.library || t.category || t.agreementType || "Library";
    if (!grouped[lib]) grouped[lib] = [];
    grouped[lib].push(t);
  });

  var groupHtml = Object.keys(grouped).sort().map(function (lib) {
    var items = grouped[lib];
    return '<details class="_eli3_chat_attach_group">' +
      '<summary>' + _esc(lib) + ' <span class="_eli3_chat_attach_count">(' + items.length + ')</span></summary>' +
      '<div class="_eli3_chat_attach_items">' +
        items.map(function (t) {
          var name = t.label || t.name || t.id;
          return '<button type="button" class="_eli3_chat_attach_item" data-tpl-id="' + _esc(t.id) + '">' +
            '📄 ' + _esc(name) + '</button>';
        }).join("") +
      '</div>' +
    '</details>';
  }).join("");

  var bodyHtml =
    '<div class="_eli3_chat_attach_body">' +
      '<div class="_eli3_chat_attach_section">' +
        '<div class="_eli3_chat_attach_secthead">📁 Upload File</div>' +
        '<input type="file" id="_eli3_chat_attach_file" accept=".txt,.docx,.pdf,application/pdf">' +
        '<div class="_eli3_chat_attach_hint">PDF, DOCX, or TXT up to 5 MB. PDF stays inline; others extract to text.</div>' +
      '</div>' +
      (templates.length
        ? '<div class="_eli3_chat_attach_section">' +
            '<div class="_eli3_chat_attach_secthead">📚 Saved Templates</div>' +
            groupHtml +
          '</div>'
        : '<div class="_eli3_chat_attach_section _eli3_chat_attach_empty">No saved templates. Use Build Draft → Templates to add some.</div>') +
    '</div>';

  showEliDialog({
    variant: "info",
    tier: "premium",
    icon: "📎",
    title: "Attach to chat",
    body: bodyHtml,
    secondary: { label: "Cancel" },
    onMount: function (overlay) {
      var fileInp = overlay.querySelector("#_eli3_chat_attach_file");
      if (fileInp) fileInp.onchange = function (e) {
        var f = e.target.files && e.target.files[0];
        if (!f) return;
        onPickFile(f);
        if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
      };
      Array.prototype.forEach.call(overlay.querySelectorAll("[data-tpl-id]"), function (btn) {
        btn.onclick = function () {
          var id = btn.getAttribute("data-tpl-id");
          var t = templates.find(function (tt) { return String(tt.id) === id; });
          if (t) onPickTemplate(t);
          if (overlay.parentNode) overlay.parentNode.removeChild(overlay);
        };
      });
    },
  });
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["ask_eli"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var analyze              = efns.analyze;
  var buildAskEliPrompt    = efns.buildAskEliPrompt;
  var buildTranslatePrompt = efns.buildTranslatePrompt;
  var buildAttachmentPrefix= efns.buildAttachmentPrefix;
  var capHistory           = efns.capHistory;
  var parseAiResponse      = efns.parseAiResponse;
  var renderCitations      = efns.renderCitations;
  var isTranslateRequest   = efns.isTranslateRequest;
  var renderChat           = vfns.renderChat;
  var renderAttachDialog   = vfns.renderAttachDialog;
  if (!analyze || !buildAskEliPrompt || !capHistory || !parseAiResponse || !renderChat) {
    eli.log.event("tool", "ask_eli_load_failed", {
      hasAnalyze: !!analyze, hasBuild: !!buildAskEliPrompt, hasCap: !!capHistory,
      hasParse: !!parseAiResponse, hasView: !!renderChat,
    });
    return;
  }

  // ─── Per-doc chat history (IDB STORE_CONFIG) ─────────────────────
  function _historyKey(docHash) { return "_chat_history_" + (docHash || "default"); }
  function _readHistory(docHash) {
    return eli.events.safeAsync(eli.storage.get("config", _historyKey(docHash)), "ask_eli.hist_read")
      .then(function (row) { return (row && Array.isArray(row.history)) ? row.history : []; })
      .catch(function () { return []; });
  }
  function _writeHistory(docHash, history) {
    return eli.events.safeAsync(eli.storage.put("config", {
      key: _historyKey(docHash), history: history, updatedAt: Date.now(),
    }), "ask_eli.hist_write").catch(function () {});
  }
  function _clearHistory(docHash) {
    return eli.events.safeAsync(eli.storage.delete("config", _historyKey(docHash)), "ask_eli.hist_clear").catch(function () {});
  }

  // ─── Doc hash (matches build_draft._bd_hashContent shape) ────────
  function _hashContent(text) {
    if (!text) return "empty";
    var s = String(text), hash = 0;
    for (var i = 0; i < s.length; i++) {
      hash = ((hash << 5) - hash) + s.charCodeAt(i);
      hash |= 0;
    }
    return "h" + (hash >>> 0).toString(36);
  }

  // ─── AskEliAnchor bookmark sweep ─────────────────────────────────
  // FROM v2 line 7138-7150. On chat entry, sweep any prior session's
  // AskEliAnchor_* bookmarks (they render as visible [ ] in Word when
  // "Show bookmarks" is on).
  function _sweepAnchors() {
    if (!eli.host || !eli.host.runRaw) return Promise.resolve();
    return eli.host.runRaw("ask_eli:anchor_sweep", function (context) {
      var bks = context.document.body.getRange().bookmarks;
      bks.load("items");
      return context.sync().then(function () {
        var items = bks.items || [];
        for (var i = 0; i < items.length; i++) {
          var b = items[i];
          if (b && b.name && b.name.indexOf("AskEliAnchor_") === 0) {
            try { b.delete(); } catch (e) {}
          }
        }
        return context.sync();
      });
    }).catch(function () { /* tolerate */ });
  }

  // ─── Doc + selection read ────────────────────────────────────────
  function _readDocAndSelection() {
    return eli.host.runRaw("ask_eli:read_doc", function (context) {
      var body = context.document.body;
      var selection = context.document.getSelection();
      body.load("text");
      selection.load("text");
      return context.sync().then(function () {
        var docText = String(body.text || "");
        var selText = String((selection && selection.text) || "");
        return {
          docText: docText,
          selectionText: selText,
          docHash: _hashContent(docText),
        };
      });
    }).catch(function (err) {
      eli.log.event("tool", "ask_eli_read_failed", { msg: err && err.message });
      return { docText: "", selectionText: "", docHash: "empty" };
    });
  }
  // Read selection only (cheaper, used by live-update path).
  function _readSelectionOnly() {
    if (!eli.host || !eli.host.runRaw) return Promise.resolve("");
    return eli.host.runRaw("ask_eli:sel_only", function (context) {
      var sel = context.document.getSelection();
      sel.load("text");
      return context.sync().then(function () { return String(sel.text || ""); });
    }).catch(function () { return ""; });
  }

  // ─── Selection live-update wire ──────────────────────────────────
  function _wireSelectionUpdates(view, ctx) {
    if (!eli.host || typeof eli.host.onDocChange !== "function") return function () {};
    var pending = null, lastSel = ctx.selectionText || "";
    function pulse() {
      if (pending) return;
      pending = setTimeout(function () {
        pending = null;
        _readSelectionOnly().then(function (sel) {
          if (sel !== lastSel) {
            lastSel = sel;
            ctx.selectionText = sel;
            view.setSelection(sel);
          }
        });
      }, 250);
    }
    var unsub = eli.host.onDocChange(pulse);
    return function () {
      if (pending) clearTimeout(pending);
      try { if (typeof unsub === "function") unsub(); } catch (e) {}
    };
  }

  // ─── Insert AskEliAnchor at current selection ────────────────────
  // Returns the bookmark name. FROM v2 line 11425.
  function _insertAnchor() {
    var name = "AskEliAnchor_" + Date.now();
    return eli.host.runRaw("ask_eli:insert_anchor", function (context) {
      var sel = context.document.getSelection();
      try { sel.insertBookmark(name); } catch (e) {}
      return context.sync().then(function () { return name; });
    }).catch(function () { return null; });
  }

  // Delete a single anchor by name. FROM v2 line 11509.
  function _deleteAnchor(name) {
    if (!name) return Promise.resolve();
    return eli.host.runRaw("ask_eli:delete_anchor", function (context) {
      var bks = context.document.body.getRange().bookmarks;
      bks.load("items");
      return context.sync().then(function () {
        var items = bks.items || [];
        for (var i = 0; i < items.length; i++) {
          if (items[i] && items[i].name === name) {
            try { items[i].delete(); } catch (e) {}
          }
        }
        return context.sync();
      });
    }).catch(function () {});
  }

  // ─── File reader (PDF / DOCX / TXT) ──────────────────────────────
  // FROM v2 chatCustomFileInput.onchange. PDF → base64 + inlineData.
  // DOCX → mammoth.extractRawText (if mammoth global is loaded).
  // TXT → TextDecoder.
  function _readFile(file) {
    return new Promise(function (resolve, reject) {
      var name = String(file.name || "attachment");
      var lower = name.toLowerCase();
      var reader = new FileReader();
      reader.onerror = function () { reject(new Error("Failed to read file")); };
      if (/\.pdf$/.test(lower)) {
        reader.onload = function () {
          var b64 = reader.result.split(",")[1];
          resolve({ kind: "pdf", name: name, mime: "application/pdf", data: b64 });
        };
        reader.readAsDataURL(file);
      } else if (/\.docx$/.test(lower)) {
        reader.onload = function () {
          if (typeof window.mammoth === "undefined" || !window.mammoth.extractRawText) {
            reject(new Error("Mammoth library not loaded — can't extract DOCX text."));
            return;
          }
          window.mammoth.extractRawText({ arrayBuffer: reader.result })
            .then(function (res) { resolve({ kind: "file", name: name, text: String(res.value || "") }); })
            .catch(function (e) { reject(new Error("DOCX parse failed: " + (e && e.message || "unknown"))); });
        };
        reader.readAsArrayBuffer(file);
      } else if (/\.(txt|csv|json|md)$/.test(lower)) {
        reader.onload = function () {
          var text;
          try { text = new TextDecoder("utf-8").decode(reader.result); }
          catch (e) { text = String(reader.result || ""); }
          resolve({ kind: "file", name: name, text: text });
        };
        reader.readAsArrayBuffer(file);
      } else {
        reject(new Error("Unsupported file type. Use PDF, DOCX, or TXT."));
      }
    });
  }

  // ─── Activity feed: per-conversation entry mutation ──────────────
  // FROM v2 _updateAskEliActivity (line 11206). The first call creates
  // a fresh activity entry; subsequent calls in the same chat session
  // append turns to `payload.turns` and update the summary.
  function _updateActivity(state, question, answerHtml, citations, opts) {
    if (!eli.activity || !eli.activity.add) return;
    opts = opts || {};
    var turn = { question: question, answer: answerHtml, citations: citations || [], at: Date.now() };
    state.activityTurns = (state.activityTurns || []).concat([turn]);
    var summary = state.activityTurns.length + " message" + (state.activityTurns.length === 1 ? "" : "s") +
      " · " + String(question).substring(0, 80);
    var icon = opts.icon || "🤖";
    var label = opts.label || "Ask ELI";
    // Activity store doesn't have a mutate-existing API in v3 today — we
    // append a new entry per turn but flag continuations via id. Future:
    // add eli.activity.update(id, patch). For now, separate entries are
    // OK; the icon + label group them visually.
    eli.activity.add({
      type: "ask-eli",
      icon: icon,
      label: label,
      summary: summary,
      payload: {
        question: question,
        answer: answerHtml,
        citations: citations || [],
        docHash: state.docHash,
        turn: state.activityTurns.length,
      },
      provenance: { timestamp: Date.now() },
    });
  }

  // ─── Action card Apply ────────────────────────────────────────────
  // FROM v2 renderActionCard apply path (line 11637-11713). Uses the
  // anchor bookmark when available; falls back to body.search.
  function _applyAction(payload) {
    var target = String(payload.target_original || "").trim();
    var proposed = String(payload.proposed_new || "");
    var anchor = payload.anchorBookmark;
    var useRedlines = !!payload.useRedlines;
    if (!target || !proposed) return Promise.reject(new Error("Missing target or proposed text"));
    return eli.host.runRaw("ask_eli:apply_action", function (context) {
      var doc = context.document;
      // Try anchor first.
      var range = null;
      if (anchor) {
        try {
          var b = doc.body.getRange().bookmarks.getItemOrNullObject(anchor);
          b.load("isNullObject");
          // Fall through to context.sync below to check.
          range = { _bookmark: b };
        } catch (e) { /* fall through */ }
      }
      // Try search fallback.
      var searchRes = doc.body.search(target.substring(0, 250), {
        matchCase: false, matchWholeWord: false, ignorePunct: true, ignoreSpace: true,
      });
      searchRes.load("items");
      return context.sync().then(function () {
        var actualRange = null;
        if (range && range._bookmark && !range._bookmark.isNullObject) {
          actualRange = range._bookmark.getRange();
          actualRange.load("text");
        } else if (searchRes.items && searchRes.items.length > 0) {
          actualRange = searchRes.items[0];
        }
        if (!actualRange) {
          throw new Error("Couldn't locate target text in document");
        }
        // Set track-changes mode.
        try {
          context.document.changeTrackingMode = useRedlines ? Word.ChangeTrackingMode.trackAll : Word.ChangeTrackingMode.off;
        } catch (e) { /* tolerate older hosts */ }
        actualRange.insertHtml(proposed, "Replace");
        return context.sync().then(function () {
          // Clean up the anchor bookmark after apply.
          if (anchor) {
            var bks = doc.body.getRange().bookmarks;
            bks.load("items");
            return context.sync().then(function () {
              for (var i = 0; i < bks.items.length; i++) {
                if (bks.items[i].name === anchor) {
                  try { bks.items[i].delete(); } catch (e) {}
                }
              }
              return context.sync();
            });
          }
        });
      });
    }).then(function () {
      return { message: useRedlines ? "✓ Applied with track changes" : "✓ Applied (clean)" };
    });
  }

  // ─── Improve-prompt helper ───────────────────────────────────────
  // FROM v2 improveBtn (line 7530+). Quick AI rewrite of the user's draft
  // question to be more precise/specific. Uses prompt key "improvePrompt"
  // if loaded; otherwise inline.
  function _improvePrompt(current) {
    if (!eli.ai || !eli.ai.complete) return Promise.resolve(current);
    var prompt = "Improve the following question to be more precise, specific, and useful when asked about a legal document. " +
      "Return ONLY the improved question — no preamble, no quotes, no explanation.\n\nORIGINAL: " + current;
    return Promise.resolve(eli.ai.complete(prompt, { sanitize: false })).then(function (out) {
      var s = String(out || "").trim().replace(/^[`"']|[`"']$/g, "");
      return s || current;
    }).catch(function () { return current; });
  }

  // ─── Doc-type heuristic (lightweight) ────────────────────────────
  // For the placeholder. Real OARS-driven type lookup lives in the
  // build_draft tool; we don't need that here.
  function _detectDocTypeLabel() {
    // FROM v2 _eliDocType global. Not ported as a separate detector
    // here — placeholder simply says "document" by default.
    return "document";
  }

  // ─── Open the chat ───────────────────────────────────────────────
  function _open(preloadOpts) {
    preloadOpts = preloadOpts || {};
    if (!eli.ai || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") showToast("Set a Gemini API key in Settings → Global first.", "warn");
      if (eli.settings && eli.settings.show) eli.settings.show();
      return;
    }
    try { eli.fsm.transition("rendering"); } catch (e) {}
    var mount = document.getElementById("_eli3_dashboard_root");

    var welcomeName = "there";
    try {
      var ident = eli.tools && eli.tools.userIdentity ? eli.tools.userIdentity() : null;
      if (ident && (ident.firstName || ident.name)) {
        welcomeName = ident.firstName || (ident.name || "").split(/\s+/)[0] || "there";
      }
    } catch (e) {}

    // Mutable per-session state.
    var ctx = {
      docText: "", selectionText: "", docHash: "empty",
      history: [],
      attachment: null,           // { kind:"pdf"|"file"|"template", name, text?, mime?, data? }
      activeTemplatePayload: null,
      scope: "attached",          // "attached" | "both"
      modifyMode: false,
      activityTurns: [],
      currentAnchor: null,
      unsubSelection: null,
      view: null,
    };

    // Sweep stale anchors, read doc, load history, then render.
    _sweepAnchors().then(function () {
      return _readDocAndSelection();
    }).then(function (read) {
      ctx.docText = read.docText;
      ctx.selectionText = read.selectionText;
      ctx.docHash = read.docHash;
      return _readHistory(ctx.docHash);
    }).then(function (history) {
      ctx.history = history;

      ctx.view = renderChat({
        mount: mount,
        history: history,
        welcomeName: welcomeName,
        docTypeLabel: _detectDocTypeLabel(),
        selectionText: ctx.selectionText,
        attachment: ctx.attachment,
        scope: ctx.scope,
        onBack: function () {
          try { if (ctx.unsubSelection) ctx.unsubSelection(); } catch (e) {}
          try { eli.fsm.transition("idle"); } catch (e) {}
          if (eli.dashboard && typeof eli.dashboard.goHome === "function") eli.dashboard.goHome();
          else if (eli.dashboard && typeof eli.dashboard.render === "function") eli.dashboard.render();
        },
        onClearHistory: function () {
          eli.ui.confirm({
            title: "Clear conversation?",
            message: "This wipes the chat history for this document. The document itself is unchanged.",
            confirmLabel: "Clear",
            variant: "danger",
          }).then(function (ok) {
            if (!ok) return;
            ctx.history = [];
            ctx.activityTurns = [];
            _clearHistory(ctx.docHash);
            ctx.view.clearScroll();
            ctx.view.addAiBubble("🤖 <strong>ELI</strong>: History cleared. What would you like to know?");
            ctx.view.focusInput();
          });
        },
        onAttachOpen: _onAttachOpen,
        onAttachClear: function () {
          ctx.attachment = null;
          ctx.activeTemplatePayload = null;
          ctx.view.setAttachment(null);
        },
        onScopeChange: function (s) { ctx.scope = s; },
        onModifyModeChange: function (mode) { ctx.modifyMode = mode; },
        onImprove: _improvePrompt,
        onCitationClick: _onCitationClick,
        onApplyAction: _applyAction,
        onRejectAction: function () { /* no-op; user can dismiss */ },
        onFollowup: function (text) {
          // Stuff into input + send. The view's _doSend will handle reset.
          var inp = mount.querySelector("#_eli3_chat_input");
          if (inp) {
            inp.value = text || "";
            inp.focus();
            // Trigger a click on the Send button (via re-fire).
            var send = mount.querySelector("#_eli3_chat_send");
            if (send) send.click();
          }
        },
        onSend: eli.events.guard(function (question, sendCtx) {
          return _runQuery(ctx, question, sendCtx);
        }, "ask_eli.send"),
      });

      // Apply preloaded context if any (FROM v2 runTrackPortAskEli).
      if (preloadOpts.context && Array.isArray(preloadOpts.context)) {
        ctx.history = capHistory(ctx.history.concat(preloadOpts.context));
      }

      // Optional restored-from-activity replay.
      if (preloadOpts.replayTurns && Array.isArray(preloadOpts.replayTurns)) {
        preloadOpts.replayTurns.forEach(function (t) {
          if (!t) return;
          if (t.question) ctx.view.addUserBubble(t.question);
          if (t.answer) ctx.view.addAiBubble(t.answer, t.citations || []);
        });
      }

      ctx.unsubSelection = _wireSelectionUpdates(ctx.view, ctx);
      ctx.view.focusInput();

      // Optional preset question — submit immediately.
      if (preloadOpts.question) {
        var inp = mount.querySelector("#_eli3_chat_input");
        var send = mount.querySelector("#_eli3_chat_send");
        if (inp && send) {
          inp.value = preloadOpts.question;
          send.click();
        }
      }
    }).catch(function (err) {
      eli.log.event("tool", "ask_eli_open_failed", { msg: err && err.message });
      if (typeof showToast === "function") showToast("Ask ELI failed: " + (err && err.message || "unknown"), "err");
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    });

    // ─── Attach modal handler ──────────────────────────────────────
    function _onAttachOpen() {
      eli.events.safeAsync(eli.storage.getAll("templates"), "ask_eli.tpls").then(function (rows) {
        rows = (rows || []).filter(function (r) { return r && r.id && String(r.id).charAt(0) !== "_"; });
        renderAttachDialog({
          templates: rows,
          onPickFile: function (file) {
            _readFile(file).then(function (att) {
              ctx.attachment = att;
              ctx.activeTemplatePayload = null;
              ctx.view.setAttachment(att);
              ctx.scope = "attached";
              ctx.view.setScope("attached");
              if (typeof showToast === "function") showToast("📎 Attached: " + att.name, "ok");
            }).catch(function (err) {
              if (typeof showToast === "function") showToast("Attach failed: " + (err && err.message || "unknown"), "err");
            });
          },
          onPickTemplate: function (t) {
            var name = t.label || t.name || t.id;
            var content = String(t.content || t.text || t.clause || "");
            ctx.attachment = { kind: "template", name: name };
            ctx.activeTemplatePayload =
              "=== ATTACHED EXTERNAL REFERENCE: " + name + " ===\n" + content + "\n";
            ctx.view.setAttachment(ctx.attachment);
            ctx.scope = "attached";
            ctx.view.setScope("attached");
            if (typeof showToast === "function") showToast("📎 Attached template: " + name, "ok");
          },
        });
      });
    }
  }

  // ─── Citation click handler (basic — locate via Word search) ────
  function _onCitationClick(cite, chip) {
    var text = String(cite.text || "").trim();
    if (!text) return;
    if (!eli.host || !eli.host.findRange) {
      // Fall back to runRaw-based search.
      eli.host.runRaw("ask_eli:cite_locate", function (context) {
        var res = context.document.body.search(text.substring(0, 250), {
          matchCase: false, matchWholeWord: false, ignorePunct: true, ignoreSpace: true,
        });
        res.load("items");
        return context.sync().then(function () {
          if (res.items && res.items.length) {
            res.items[0].select();
            return context.sync();
          }
          throw new Error("not found");
        });
      }).then(function () {
        chip.classList.add("_eli3_chat_cite_found");
        setTimeout(function () { chip.classList.remove("_eli3_chat_cite_found"); }, 1500);
      }).catch(function () {
        chip.classList.add("_eli3_chat_cite_miss");
        setTimeout(function () { chip.classList.remove("_eli3_chat_cite_miss"); }, 1500);
      });
    }
  }

  // ─── Run the AI query — three modes ──────────────────────────────
  // FROM v2 runChatQuery (line 11329). Three branches:
  //  - Translate (regex match → buildTranslatePrompt)
  //  - Attached-only (skip Word.run; PDF inlineData when applicable)
  //  - Live or both (re-read doc + selection; insert anchor; build prompt)
  function _runQuery(ctx, question, sendCtx) {
    // Update activity-feed source (count chat messages).
    try {
      if (eli.stats && eli.stats.record) eli.stats.record("chatMessages");
    } catch (e) {}

    var att = ctx.attachment;
    var hasAttachment = !!att;
    var scope = hasAttachment ? (ctx.scope || "attached") : "live";
    var includeAttachments = hasAttachment && (scope === "attached" || scope === "both");
    var includeLive = !hasAttachment || scope === "live" || scope === "both";

    // Translate path — independent of attachment.
    if (isTranslateRequest && isTranslateRequest(question)) {
      return _runTranslate(ctx, question);
    }

    // Build attachment prefix once (used by both attached-only + both paths).
    var attachmentPrefix = "";
    var inlineData = null;
    if (includeAttachments) {
      var prefixIn = {
        activeTemplatePayload: ctx.activeTemplatePayload || "",
        attachedText: (att.kind === "file") ? att.text : "",
        attachedName: att.name || "",
        attachedPdfMarker: (att.kind === "pdf"),
      };
      attachmentPrefix = buildAttachmentPrefix ? buildAttachmentPrefix(prefixIn) : "";
      if (att.kind === "pdf" && att.data && att.mime) {
        inlineData = { mimeType: att.mime, data: att.data };
      }
    }

    var token = eli.cancel.token();
    try { eli.fsm.transition("scanning"); } catch (e) {}

    // Attached-only path — skip Word.run.
    if (includeAttachments && !includeLive) {
      var attLabel = (att.kind === "pdf") ? (att.name || "Attached PDF")
        : (att.kind === "file") ? (att.name || "Attached File")
        : (att.name || "Attached");
      return analyze({
        question: question,
        docText: "",
        selectionText: "",
        history: ctx.history,
        attachmentPrefix: attachmentPrefix,
        inlineData: inlineData,
        modifyMode: !!sendCtx.modifyMode,
        signal: token.signal,
        docHash: ctx.docHash,
      }, {
        ai: eli.ai, host: eli.host,
        buildPrompt: buildAskEliPrompt,
        capHistory: capHistory,
        parseAiResponse: parseAiResponse,
      }).then(function (result) {
        return _finalizeResult(ctx, question, result, {
          hybridNote: '<span class="_eli3_chat_hybrid_icon">📎</span> Source: ' + attLabel,
        });
      });
    }

    // Live path (with optional both) — re-read + insert anchor + run.
    return _readDocAndSelection().then(function (read) {
      ctx.docText = read.docText;
      ctx.selectionText = read.selectionText;
      ctx.docHash = read.docHash;
      ctx.view.setSelection(read.selectionText);

      // Anchor insertion when there's a selection (for action-card apply).
      var anchorPromise = (read.selectionText && read.selectionText.trim().length > 4)
        ? _insertAnchor()
        : Promise.resolve(null);

      return anchorPromise.then(function (anchorName) {
        ctx.currentAnchor = anchorName;
        return analyze({
          question: question,
          docText: read.docText,
          selectionText: read.selectionText,
          history: ctx.history,
          attachmentPrefix: scope === "both" ? attachmentPrefix : "",
          inlineData: scope === "both" ? inlineData : null,
          modifyMode: !!sendCtx.modifyMode,
          hasRedlines: false,    // redline detection deferred to follow-up port
          roster: null,
          useAnchors: false,
          signal: token.signal,
          docHash: read.docHash,
        }, {
          ai: eli.ai, host: eli.host,
          buildPrompt: buildAskEliPrompt,
          capHistory: capHistory,
          parseAiResponse: parseAiResponse,
        }).then(function (result) {
          // Forward the anchor to action card so Apply can use it.
          if (result.action === "replace_text") result.anchorBookmark = anchorName;
          var hybrid = (scope === "both")
            ? '<span class="_eli3_chat_hybrid_icon">🔍</span> Analyzed Selection + Document Context'
            : (read.selectionText && read.selectionText.trim().length > 4
                ? '<span class="_eli3_chat_hybrid_icon">🔍</span> Analyzed Selection + Document Context'
                : null);
          // Delete the anchor immediately for non-action responses.
          if (result.action !== "replace_text" && anchorName) {
            _deleteAnchor(anchorName);
            ctx.currentAnchor = null;
          }
          return _finalizeResult(ctx, question, result, { hybridNote: hybrid });
        });
      });
    });
  }

  // Finalize: persist history, render citations, log activity.
  function _finalizeResult(ctx, question, result, extras) {
    extras = extras || {};
    ctx.history = result.history;
    _writeHistory(ctx.docHash, result.history);
    try { eli.fsm.transition("rendering"); } catch (e) {}
    if (result.action === "replace_text") {
      _updateActivity(ctx, question, "📝 Action card: " + (result.explanation || "Modification proposed"), [], {});
      return result;
    }
    // Render citations into the answer HTML.
    var renderedAnswer = result.answer;
    if (renderCitations && Array.isArray(result.citations) && result.citations.length) {
      var cited = renderCitations(result.answer, result.citations);
      renderedAnswer = cited.html;
    }
    _updateActivity(ctx, question, renderedAnswer, result.citations, {});
    return {
      answer: renderedAnswer,
      citations: result.citations,
      followups: result.followups,
      hybridNote: extras.hybridNote || null,
    };
  }

  // Translate path — separate prompt + render.
  function _runTranslate(ctx, question) {
    return _readDocAndSelection().then(function (read) {
      ctx.docText = read.docText;
      ctx.selectionText = read.selectionText;
      ctx.docHash = read.docHash;
      var src = read.selectionText && read.selectionText.length > 4 ? read.selectionText : read.docText;
      var prompt = buildTranslatePrompt({
        question: question,
        sourceText: src,
        sourceHtml: src,    // best-effort — we don't have html readily here
      });
      return Promise.resolve(eli.ai.complete(prompt, { sanitize: false })).then(function (raw) {
        var parsed = parseAiResponse(raw);
        var html = parsed.html || parsed.text || String(raw || "");
        var hasTables = !!parsed.hasTables;
        // Append to history as a labeled turn.
        ctx.history = capHistory(ctx.history.concat([
          { role: "user", content: question },
          { role: "model", content: "🌐 Translation: " + (hasTables ? "(table preserved)" : html.substring(0, 200)) },
        ]));
        _writeHistory(ctx.docHash, ctx.history);
        _updateActivity(ctx, question, html, [], { icon: "🌐", label: "Ask ELI · Translate" });
        return { translate: { hasTables: hasTables, html: html } };
      }).catch(function (err) {
        return { answer: '⚠️ Translation failed: <code>' + String(err && err.message || "unknown").replace(/</g, "&lt;") + '</code>' };
      });
    });
  }

  // ─── Channels ────────────────────────────────────────────────────
  eli.register({
    tile: { app_ask_eli: function () {
      try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAskEli"); } catch (e) {}
      _open();
    } },
    // Programmatic launch with a preset question (FROM v2 submitHomeChat /
    // fireChipQuery). Caller passes { question, context?, replayTurns? }.
    ask_eli: { compose: function (opts) { _open(opts || {}); } },
    // Activity-feed restoration (FROM v2 line 1168). Re-opens chat and
    // replays prior turns into the bubble area.
    activity_restore: { "ask-eli": function (payload) {
      _open({
        replayTurns: payload && payload.turns
          ? payload.turns
          : (payload && payload.question
              ? [{ question: payload.question, answer: payload.answer || "", citations: payload.citations || [] }]
              : []),
      });
    } },
  });

  eli.log.event("tool", "ask_eli_initialized", {});
}

jsonTools.css:
/* ask_eli tool styles. Injected as <style data-tool="ask_eli">. */

/* Reuses _eli3_ae_root + _eli3_ae_bar from auto_emailer for header
   consistency (dark navy banner, gold accent rule). Tool-specific extras
   below; nothing duplicates a kernel-side style. */

._eli3_chat_root {
  display: flex; flex-direction: column;
  width: 100%; height: 100%;
  background: #fff;
  overflow: hidden;
}
._eli3_chat_clear {
  background: rgba(255,255,255,0.10);
  border: 1px solid rgba(255,255,255,0.20);
  color: #cbd5e1;
  font-size: 14px; line-height: 1;
  padding: 6px 10px;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_chat_clear:hover {
  background: rgba(201,162,39,0.25);
  border-color: rgba(201,162,39,0.6);
  color: #f2d866;
  transform: translateY(-1px);
}

/* Scrolling bubble area — fills remaining vertical space; min-height 0
   so it shrinks correctly inside the column flex parent. */
._eli3_chat_scroll {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 14px;
  display: flex; flex-direction: column; gap: 10px;
  background: #f8fafc;
}

/* Bubble base — centered column, full-width chat layout. */
._eli3_chat_bubble {
  max-width: 92%;
  padding: 10px 14px;
  font: 500 13px/1.5 'Inter', sans-serif;
  word-wrap: break-word;
  position: relative;
}
._eli3_chat_bubble_user {
  align-self: flex-end;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  white-space: pre-wrap;
}
._eli3_chat_bubble_ai {
  align-self: flex-start;
  background: #fff;
  color: #0f172a;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #c9a227;
}
._eli3_chat_bubble_ai b, ._eli3_chat_bubble_ai strong { color: #0d1b2a; }
._eli3_chat_bubble_ai ul { margin: 6px 0; padding-left: 20px; }
._eli3_chat_bubble_ai li { margin: 2px 0; }
._eli3_chat_bubble_ai code {
  font: 600 11px/1 'JetBrains Mono', monospace;
  background: #f1f5f9;
  color: #b91c1c;
  padding: 1px 5px;
  border-radius: 2px;
}
._eli3_chat_bubble_system {
  align-self: stretch;
  background: #fff7ed;
  border: 1px solid #fdba74;
  color: #7c2d12;
  font: 500 12px/1.4 'Inter', sans-serif;
  text-align: center;
}
._eli3_chat_welcome_hint {
  font: 400 11px/1.4 'Inter', sans-serif;
  color: #64748b;
  font-style: normal;
}

/* Loader bubble — three pulsing dots. */
._eli3_chat_bubble_loader {
  align-self: flex-start;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-left: 3px solid #c9a227;
  display: inline-flex; align-items: center; gap: 4px;
  padding: 14px 16px;
}
._eli3_chat_dot {
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #94a3b8;
  display: inline-block;
  animation: _eli3_chat_pulse 1.4s infinite ease-in-out both;
}
._eli3_chat_dot:nth-child(2) { animation-delay: 0.16s; }
._eli3_chat_dot:nth-child(3) { animation-delay: 0.32s; }
@keyframes _eli3_chat_pulse {
  0%, 80%, 100% { transform: scale(0.6); opacity: 0.5; }
  40%           { transform: scale(1.0); opacity: 1.0; }
}

/* Selection-preview chip — sits above the input row. Slides in/out when
   user highlights text in the document. */
._eli3_chat_selpreview {
  flex: 0 0 auto;
  display: flex; align-items: flex-start; gap: 8px;
  padding: 8px 14px;
  background: #fef9e7;
  border-top: 1px solid #fde68a;
  font: 500 11px/1.4 'Inter', sans-serif;
  color: #78350f;
}
._eli3_chat_selpreview[hidden] { display: none; }
._eli3_chat_selpreview_label {
  flex: 0 0 auto;
  font-weight: 700;
  color: #92400e;
  white-space: nowrap;
}
._eli3_chat_selpreview_text {
  flex: 1 1 auto;
  font-style: italic;
  color: #57534e;
  overflow: hidden;
  text-overflow: ellipsis;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

/* Input row — textarea + send button. Anchored to the bottom; stays
   visible even when the bubble area scrolls. */
._eli3_chat_inputrow {
  flex: 0 0 auto;
  display: flex; align-items: flex-end; gap: 8px;
  padding: 10px 14px 12px;
  background: #fff;
  border-top: 1px solid #e2e8f0;
}
._eli3_chat_input {
  flex: 1 1 auto;
  resize: none;
  min-height: 36px;
  max-height: 96px;
  padding: 8px 10px;
  font: 500 13px/1.4 'Inter', sans-serif;
  color: #0f172a;
  background: #fff;
  border: 1px solid #cbd5e1;
  outline: none;
  box-sizing: border-box;
}
._eli3_chat_input:focus {
  border-color: #1565c0;
  box-shadow: 0 0 0 2px rgba(21, 101, 192, 0.18);
}
._eli3_chat_send {
  flex: 0 0 auto;
  width: 40px; height: 40px;
  display: inline-flex; align-items: center; justify-content: center;
  font-size: 18px; line-height: 1;
  color: #fff;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  border: 1px solid #0d47a1;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: 0 2px 6px rgba(21, 101, 192, 0.25);
}
._eli3_chat_send:hover:not(:disabled) {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(21, 101, 192, 0.35);
}
._eli3_chat_send:disabled {
  opacity: 0.5;
  cursor: progress;
}

/* Mobile-narrow squeeze — tiles + chat bubbles need to stay readable. */
@media (max-width: 380px) {
  ._eli3_chat_bubble { max-width: 100%; padding: 8px 12px; font-size: 12px; }
  ._eli3_chat_inputrow { padding: 8px 10px; gap: 6px; }
  ._eli3_chat_send { width: 36px; height: 36px; }
}


/* =====================================================================
   Toolbar, scope bar, attach, modes
   ===================================================================== */
._eli3_chat_inputrow {
  flex-direction: column;
  align-items: stretch;
  gap: 6px;
}
._eli3_chat_toolbar {
  flex: 0 0 auto;
  display: flex; align-items: center; gap: 6px;
}
._eli3_chat_tool {
  flex: 0 0 auto;
  height: 36px;
  min-width: 36px;
  padding: 0 8px;
  display: inline-flex; align-items: center; justify-content: center; gap: 4px;
  font: 600 11px/1 'Inter', sans-serif;
  background: linear-gradient(to bottom, #f7f9fa 0%, #dce3e8 100%);
  color: #475569;
  border: 1px solid #b0bec5;
  cursor: pointer;
  transition: all 0.15s;
  user-select: none;
}
._eli3_chat_tool:hover:not(:disabled) {
  background: linear-gradient(to bottom, #fff 0%, #e3f2fd 100%);
  color: #1565c0;
  border-color: #90caf9;
}
._eli3_chat_tool:disabled { opacity: 0.5; cursor: progress; }

._eli3_chat_drafttoggle {
  position: relative;
  padding-right: 12px;
}
._eli3_chat_drafttoggle input[type="checkbox"] {
  margin: 0 4px 0 0;
  accent-color: #1565c0;
}
._eli3_chat_drafttoggle:has(input:checked) {
  background: #1565c0;
  color: #fff;
  border-color: #0d47a1;
}

._eli3_chat_attach_on {
  background: #e8f5e9 !important;
  color: #2e7d32 !important;
  border-color: #66bb6a !important;
  font-weight: 700;
  max-width: 160px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
._eli3_chat_attach_x {
  margin-left: 6px;
  color: #c62828;
  font-weight: 700;
}

._eli3_chat_contexthint {
  flex: 1 1 auto;
  text-align: right;
  font: 500 10px/1.2 'Inter', sans-serif;
  color: #94a3b8;
  font-style: italic;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  padding: 0 6px;
}
._eli3_chat_contexthint_active {
  color: #1565c0;
  font-style: normal;
  font-weight: 600;
}

._eli3_chat_scopebar {
  flex: 0 0 auto;
  display: flex; gap: 4px;
  padding: 6px 14px;
  background: #f8fafc;
  border-top: 1px solid #e2e8f0;
}
._eli3_chat_scopebar[hidden] { display: none; }
._eli3_chat_scopeseg {
  flex: 1 1 auto;
  padding: 6px 12px;
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  background: #fff;
  border: 1px solid #cbd5e1;
  color: #475569;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_chat_scopeseg:hover { border-color: #93c5fd; color: #1565c0; }
._eli3_chat_scopeseg_active {
  background: #1565c0;
  border-color: #0d47a1;
  color: #fff;
}

/* Selection chip extensions */
._eli3_chat_selpreview_top {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 4px;
}
._eli3_chat_selpreview_dismiss {
  background: none; border: none; cursor: pointer;
  font: 700 14px/1 'Inter', sans-serif;
  color: #b45309;
  padding: 0 4px;
}
._eli3_chat_selpreview_dismiss:hover { color: #7c2d12; }
._eli3_chat_selpreview_rewrite {
  display: inline-flex; align-items: center; gap: 5px;
  margin-top: 6px;
  font: 700 10px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #92400e;
  cursor: pointer;
}
._eli3_chat_selpreview_rewrite input[type="checkbox"] {
  accent-color: #b45309;
}

/* Action cards */
._eli3_chat_actioncard {
  align-self: stretch;
  max-width: 100%;
  border: 2px solid #1565c0 !important;
  border-left: 5px solid #1565c0 !important;
  background: #fff !important;
  padding: 0 !important;
}
._eli3_chat_actioncard_head {
  background: linear-gradient(135deg, #0d1b2a 0%, #1b263b 100%);
  color: #fff;
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.6px;
  padding: 10px 14px;
  border-bottom: 3px solid #c9a227;
}
._eli3_chat_actioncard_explanation {
  padding: 10px 14px;
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #475569;
  background: #f8fafc;
  border-bottom: 1px solid #e2e8f0;
}
._eli3_chat_actioncard_diff {
  padding: 12px 14px;
  font: 500 13px/1.6 'Georgia', serif;
  color: #0f172a;
  background: #fff;
  word-wrap: break-word;
  border-bottom: 1px solid #e2e8f0;
  max-height: 240px;
  overflow-y: auto;
}
._eli3_chat_diff_add {
  background: #d1fae5;
  color: #065f46;
  text-decoration: underline;
  text-decoration-color: #10b981;
  font-weight: 700;
}
._eli3_chat_diff_del {
  background: #fee2e2;
  color: #991b1b;
  text-decoration: line-through;
}
._eli3_chat_diff_empty { color: #94a3b8; font-style: italic; }
._eli3_chat_actioncard_redline {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 8px 14px;
  font: 600 11px/1.3 'Inter', sans-serif;
  color: #475569;
  background: #fff;
  cursor: pointer;
  user-select: none;
}
._eli3_chat_actioncard_redline input[type="checkbox"] { accent-color: #1565c0; }
._eli3_chat_actioncard_actions {
  display: flex; gap: 8px;
  padding: 10px 14px;
  background: #f8fafc;
  border-top: 1px solid #e2e8f0;
}
._eli3_chat_actioncard_reject {
  flex: 1;
  padding: 9px 14px;
  font: 700 11px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  background: linear-gradient(180deg, #fff 0%, #f1f5f9 100%);
  border: 1px solid #cbd5e1;
  color: #475569;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_chat_actioncard_reject:hover { background: #fef2f2; border-color: #fca5a5; color: #b91c1c; }
._eli3_chat_actioncard_apply {
  flex: 1.6;
  padding: 9px 14px;
  font: 700 12px/1 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  background: linear-gradient(135deg, #1565c0 0%, #0d47a1 100%);
  color: #fff;
  border: 1px solid #0d47a1;
  cursor: pointer;
  transition: all 0.15s;
  box-shadow: 0 2px 6px rgba(21, 101, 192, 0.25);
}
._eli3_chat_actioncard_apply:hover:not(:disabled) {
  background: linear-gradient(135deg, #1d4ed8 0%, #1565c0 100%);
  transform: translateY(-1px);
}
._eli3_chat_actioncard_apply:disabled { opacity: 0.6; cursor: progress; }
._eli3_chat_actioncard_status {
  padding: 8px 14px;
  font: 600 11px/1.3 'Inter', sans-serif;
  color: #2e7d32;
  background: #f0fdf4;
  border-top: 1px solid #bbf7d0;
}
._eli3_chat_actioncard_status_err {
  color: #b91c1c;
  background: #fef2f2;
  border-top-color: #fecaca;
}
._eli3_chat_actioncard_done { opacity: 0.85; }

/* Citation chips, follow-ups, hybrid note, translate */
._eli3_chat_cite {
  display: inline-block;
  background: #fef3c7;
  color: #92400e;
  border: 1px solid #fde68a;
  border-radius: 50%;
  width: 18px; height: 18px;
  font-size: 9px;
  text-align: center;
  line-height: 16px;
  cursor: pointer;
  vertical-align: 1px;
  margin: 0 1px;
  user-select: none;
  transition: all 0.15s;
}
._eli3_chat_cite:hover {
  background: #f59e0b;
  color: #fff;
  border-color: #d97706;
  transform: scale(1.1);
}
._eli3_chat_cite_found {
  background: #d1fae5 !important;
  color: #065f46 !important;
  border-color: #10b981 !important;
}
._eli3_chat_cite_miss {
  background: #fee2e2 !important;
  color: #991b1b !important;
  border-color: #ef4444 !important;
}

._eli3_chat_followups {
  display: flex; flex-wrap: wrap; gap: 6px;
  margin-top: 10px; padding-top: 10px;
  border-top: 1px solid #ececec;
}
._eli3_chat_followup {
  flex: 1 1 auto;
  max-width: 100%;
  padding: 6px 10px;
  font: 600 11px/1.3 'Inter', sans-serif;
  color: #1565c0;
  background: #f0f4f8;
  border: 1px solid #d0d7de;
  text-align: left;
  cursor: pointer;
  white-space: normal;
  word-break: break-word;
  transition: background 0.15s;
}
._eli3_chat_followup:hover {
  background: #e1e8f0;
  border-color: #1565c0;
}

._eli3_chat_hybrid {
  margin-bottom: 6px;
  font: 600 9px/1.2 'Inter', sans-serif;
  color: #1565c0;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  display: flex; align-items: center; gap: 4px;
}
._eli3_chat_hybrid_icon { font-size: 11px; }

._eli3_chat_translate_label {
  font: 700 10px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #047857;
  margin-bottom: 6px;
  padding-bottom: 4px;
  border-bottom: 1px solid #6ee7b7;
}
._eli3_chat_translate_table {
  overflow-x: auto;
  max-width: 100%;
}
._eli3_chat_translate_table table { border-collapse: collapse; font-size: 11px; }
._eli3_chat_translate_table td, ._eli3_chat_translate_table th {
  border: 1px solid #cbd5e1;
  padding: 4px 8px;
  vertical-align: top;
}

/* Attach modal */
._eli3_chat_attach_body {
  display: flex; flex-direction: column; gap: 14px;
  padding: 4px 0;
}
._eli3_chat_attach_section {
  padding: 12px 14px;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}
._eli3_chat_attach_secthead {
  font: 700 11px/1.2 'Inter', sans-serif;
  text-transform: uppercase; letter-spacing: 0.5px;
  color: #1565c0;
  margin-bottom: 8px;
}
._eli3_chat_attach_section input[type="file"] {
  display: block;
  width: 100%;
  padding: 6px;
  font: 500 12px/1 'Inter', sans-serif;
  border: 1px dashed #cbd5e1;
  background: #fff;
}
._eli3_chat_attach_hint {
  margin-top: 6px;
  font: 400 10px/1.4 'Inter', sans-serif;
  color: #94a3b8;
  font-style: italic;
}
._eli3_chat_attach_empty {
  font: 500 12px/1.5 'Inter', sans-serif;
  color: #94a3b8;
  font-style: italic;
  text-align: center;
}
._eli3_chat_attach_group { margin: 4px 0; }
._eli3_chat_attach_group summary {
  font: 700 11px/1.2 'Inter', sans-serif;
  color: #475569;
  cursor: pointer;
  padding: 4px 0;
  list-style: none;
}
._eli3_chat_attach_group summary::before {
  content: "▸ ";
  font-size: 9px;
  color: #94a3b8;
}
._eli3_chat_attach_group[open] summary::before { content: "▾ "; }
._eli3_chat_attach_count { color: #94a3b8; font-weight: 500; }
._eli3_chat_attach_items {
  display: flex; flex-direction: column; gap: 4px;
  margin-top: 4px;
  margin-left: 12px;
}
._eli3_chat_attach_item {
  text-align: left;
  padding: 6px 10px;
  font: 500 11px/1.3 'Inter', sans-serif;
  color: #0f172a;
  background: #fff;
  border: 1px solid #e2e8f0;
  cursor: pointer;
  transition: all 0.15s;
}
._eli3_chat_attach_item:hover {
  background: #eff6ff;
  border-color: #93c5fd;
  color: #1565c0;
}
